    ('BMO', 'BMO', '<p>* BAIXA MASSA ÓSSEA.</p>', '* BAIXA MASSA ÓSSEA.', 'Normal.dotx'),
    ('boc', 'boc', '<p>* Bócio difuso, normovascularizado ao Doppler + Discretas alterações texturais da glândula - tireoidite autoimune em fase inicial? Outra etiologia?</p>
