    ('CALciP', 'CALciP', '<p>Parênquima com textura e ecogenicidade usuais, notando-se calcificações em grumos ao redor da uretra e na topografia de cápsula cirúrgica (freqüentes e sem significado clínico). </p>', 'Parênquima com textura e ecogenicidade usuais, notando-se calcificações em grumos ao redor da uretra e na topografia de cápsula cirúrgica (freqüentes e sem significado clínico).', 'Normal.dotx'),
    ('CALcit', 'CALcit', '<p>Observamos várias estruturas ecogênicas, sem sombra sônica e diâmetro máximo de 1 mm, dispersas pelo parênquima bilateralmente. Entre as calcifica-ções, a textura é homogênea, com ecogenicidade usual. </p>', 'Observamos várias estruturas ecogênicas, sem sombra sônica e diâmetro máximo de 1 mm, dispersas pelo parênquima bilateralmente. Entre as calcifica-ções, a textura é homogênea, com ecogenicidade usual.', 'Normal.dotx'),
