), medico_alvo as (
  select lm.medico_id
  from public.laudos_medicos lm
  join public.medicos m on m.id = lm.medico_id
  where public.normalizar_nome_medico_laudos(m.nome) = public.normalizar_nome_medico_laudos('Dr VINICIUS')
  limit 1
)
insert into public.laudos_autotextos (medico_id, nome, abreviacao, conteudo_html, conteudo_texto, origem_arquivo)
select medico_alvo.medico_id, dados.nome, dados.abreviacao, dados.conteudo_html, dados.conteudo_texto, dados.origem_arquivo
from medico_alvo cross join dados
on conflict (medico_id, lower(btrim(abreviacao))) do update set
  nome = excluded.nome,
  conteudo_html = excluded.conteudo_html,
  conteudo_texto = excluded.conteudo_texto,
  origem_arquivo = excluded.origem_arquivo,
  atualizado_em = now();

